insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('basin', 'intermediate', 'module', 'm01-from-a-snapshot-to-a-clock', 1, 'What does the Professional tier add to the Associate tier''s work?', '["The mass of hydrocarbon generated and expelled by the source rock.", "A transient heat solver that replaces the steady two-layer column with backward Euler time stepping.", "A clock: kinetic integrators that turn a temperature history into maturity and conversion.", "A burial history reconstructed from decompacted thicknesses."]'::jsonb, 2, 'The Associate tier''s snapshots had no time axis. This tier adds the two kinetic clocks. Transient heat and masses belong to the Expert tier, and burial geometry was already the Associate tier''s.'),
  ('basin', 'intermediate', 'module', 'm01-from-a-snapshot-to-a-clock', 2, 'Which state produces the vitrinite reflectance?', '["The vitrinite state, with the fixed published Easy%Ro weights.", "Either state; they are interchangeable read-outs of the same integrator.", "The kerogen state, once its potentials are normalised.", "The average of the two states'' reacted fractions."]'::jsonb, 0, 'Ro comes only from the vitrinite state. The kerogen state produces the transformation ratio, and conflating the two was the audited headline defect.'),
  ('basin', 'intermediate', 'module', 'm01-from-a-snapshot-to-a-clock', 3, 'Why are the vitrinite parameters deliberately not editable?', '["Because they are stored in a compiled library that the app cannot modify.", "Because editing them would break the transformation ratio.", "Because Sweeney and Burnham''s licence forbids modification.", "Because reflectance is the calibration channel."]'::jsonb, 3, 'A retunable thermometer is not a thermometer. Measured Ro is what basin models are judged against. If describing your source rock could move the model''s Ro, calibration would become circular. The kerogen spectrum, by contrast, is legitimately editable data.'),
  ('basin', 'intermediate', 'module', 'm01-from-a-snapshot-to-a-clock', 4, 'A colleague''s software changes its reported Ro when they switch kerogen type from II to III. What does that prove?', '["Their heating rate convention differs from the fixtures''.", "The software drives reflectance from the kerogen state.", "Type III''s higher activation energies are being applied to the vitrinite state.", "Nothing; a small Ro shift with kerogen type is expected behaviour."]'::jsonb, 1, 'Its calibrations cannot be trusted. Ro must be computed from the fixed vitrinite state, which no kerogen edit reaches. Software whose Ro moves with kerogen type has conflated the two clocks.'),
  ('basin', 'intermediate', 'module', 'm01-from-a-snapshot-to-a-clock', 5, 'What is the Arrhenius rate constant formula as the engine evaluates it?', '["k = A exp(-E / T) with E in kcal/mol and T in degC, the publication''s own unit convention.", "k = A exp(-E x 4184 / (8.314 T)) with E in kcal/mol and T in kelvin.", "k = A exp(-E c / R T) with c the compaction constant.", "k = A T exp(-E / R) with A scaled per bin."]'::jsonb, 1, 'E is stored in kcal/mol, converted with 4184 J/kcal, divided by R = 8.314 J/(mol K) times the absolute temperature. Getting these units wrong destroys the answer rather than degrading it.'),
  ('basin', 'intermediate', 'module', 'm01-from-a-snapshot-to-a-clock', 6, 'At 100 degC, the 46 kcal/mol bin''s rate constant is 1.1411620329306917e-14 per second. What is it at 110 degC?', '["About 2.3e-14 per second, roughly double.", "Unchanged; the rate depends on the bin, not the temperature.", "About 1.14e-13, exactly ten times higher.", "About 5.76e-14 per second."]'::jsonb, 3, 'Over five times higher. Ten degrees multiplies this bin''s rate by 5.048799411678268, to 5.761498200490052e-14. The biology rule of doubling per 10 degC badly understates kerogen kinetics.'),
  ('basin', 'intermediate', 'module', 'm01-from-a-snapshot-to-a-clock', 7, 'How much does the 46 kcal bin''s rate rise between 100 and 150 degC?', '["By a factor of about 1526.", "By a factor of about 5.", "By a factor of about 25.", "By about three orders of magnitude per degree."]'::jsonb, 0, 'Fifty degrees multiplies the rate by 1526.0957738173342, roughly three orders of magnitude in total. Per ten degrees it is about a factor of five.'),
  ('basin', 'intermediate', 'module', 'm01-from-a-snapshot-to-a-clock', 8, 'At one temperature, the rates of the 34 and 72 kcal bins differ by a factor of about', '["fifteen, the spacing between adjacent bins.", "one thousand, the unit conversion factor.", "1e22, so the ladder spans reactions from fast to effectively never.", "1e6, about the gap between a human lifetime and a megayear of geological time."]'::jsonb, 2, 'At 100 degC the ratio k(34)/k(72) is 1.807e22. Some bins react in years, some never, and maturation is the boundary sweeping up the ladder as temperature rises.'),
  ('basin', 'intermediate', 'module', 'm01-from-a-snapshot-to-a-clock', 9, 'Why does a single first-order reaction fail to describe vitrinite maturation?', '["Because vitrinite reflects light anisotropically.", "Because the frequency factor changes with maturity.", "Because a single reaction cannot be integrated over a temperature history that changes with time.", "Because real maturation is drawn out smoothly over some 100 degC of burial."]'::jsonb, 3, 'Needs staggered energies. One reaction would switch on over a narrow temperature interval. Twenty reactions with staggered activation energies blend into the smooth, wide rise that measured reflectance actually shows.'),
  ('basin', 'intermediate', 'module', 'm01-from-a-snapshot-to-a-clock', 10, 'What is the half-life of the 46 kcal bin at 100 degC?', '["About 1.9 thousand years.", "About 1300 years.", "About 1.9 Ma.", "About 60 Ma."]'::jsonb, 2, 'ln2 / k with k = 1.1411620329306917e-14 per second gives 6.074e13 s, which is 1.926 Ma. At 150 degC, with the rate 1526 times higher, the same bin''s half-life is about 1300 years.'),
  ('basin', 'intermediate', 'module', 'm01-from-a-snapshot-to-a-clock', 11, 'In the panel, the three ramp curves are drawn together because', '["the engine computes the three ramps in one pass, so drawing them separately would cost three runs.", "their ordering and widening separation with temperature is itself the lesson.", "the capstone grades all three at 150 degC.", "averaging them approximates a real basin''s heating."]'::jsonb, 1, 'The slow ramp sits highest at every temperature and the gaps widen as maturity grows. Only the rate 3 and rate 1 values at 150 degC are graded; rate 10 is pattern.'),
  ('basin', 'intermediate', 'module', 'm01-from-a-snapshot-to-a-clock', 12, 'Which quantities does the kinetics panel compute from closed forms rather than integration?', '["Ro at zero reaction and Ro at full reaction.", "The transformation ratios at 10 and 50 Ma.", "The crossing temperatures of Ro 0.5 and 1.0.", "The 150 degC readings of the three ramps."]'::jsonb, 0, 'The anchors are exp(-1.6) and exp(-1.6 + 3.7 x 0.85), evaluated directly. They never move whatever the controls do, which makes them the panel''s own quality control.'),
  ('basin', 'intermediate', 'module', 'm01-from-a-snapshot-to-a-clock', 13, 'The tier hands you temperature tracks instead of computing them so that', '["kinetic results can be checked against fixtures with no burial model standing in the way.", "the fixtures stay small enough to run in a browser panel.", "heating rates can be pushed beyond anything a burial history under real heat flow could produce.", "the same tracks can be reused by every kerogen type."]'::jsonb, 0, 'Isolating the kinetics is the same teaching decision the Associate tier made with its steady column: learn each stage where it can be checked by hand, then chain them in the Expert tier.'),
  ('basin', 'intermediate', 'module', 'm01-from-a-snapshot-to-a-clock', 14, 'Which question belongs to the kerogen clock rather than the vitrinite clock?', '["How mature is this rock compared with a measured sample?", "What fraction of the source''s generative potential has reacted?", "At what temperature does this history cross Ro 1.0?", "What reflectance would a laboratory report for this history under oil immersion measurement?"]'::jsonb, 1, 'Converted potential is the kerogen state''s read-out, the transformation ratio, which later becomes mass. The other three are all reflectance questions, owned by the vitrinite state.'),
  ('basin', 'intermediate', 'module', 'm01-from-a-snapshot-to-a-clock', 15, 'Both kinetic states advance using', '["the vitrinite integrator, with the kerogen state derived from F through the shared energy grid.", "separate integrators tuned to each state''s stiffness.", "the same kineticStep function, differing only in parameters and read-out.", "analytic solutions that avoid stepping entirely."]'::jsonb, 2, 'One function advances both: every bin decays as x exp(-k dt). The difference between the clocks is entirely in spectra and read-outs, never in mechanics.'),
  ('basin', 'intermediate', 'module', 'm02-the-easy-ro-scheme', 1, 'The Easy%Ro activation energy grid is', '["34 to 72 kJ/mol in steps of 2, twenty bins.", "10 to 100 kcal/mol in steps of 5, nineteen bins.", "34 to 72 kcal/mol in steps of 2, twenty bins.", "a continuous distribution sampled at twenty random points."]'::jsonb, 2, 'Twenty bins from 34 to 72 kcal/mol, step 2. The units are kcal/mol; the engine converts to joules inside the exponent.'),
  ('basin', 'intermediate', 'module', 'm02-the-easy-ro-scheme', 2, 'The published Easy%Ro weights sum to', '["0.85, and the read-out is calibrated on that unnormalised scale.", "1.00, as any proper distribution must.", "0.85, an acknowledged rounding artefact left uncorrected since the 1990 publication.", "whatever the kerogen type''s potentials sum to."]'::jsonb, 0, 'F runs from 0 to 0.85 by design, and exp(-1.6 + 3.7 F) is calibrated against exactly that scale. Normalising to 1 corrupts every reflectance computed afterwards.'),
  ('basin', 'intermediate', 'module', 'm02-the-easy-ro-scheme', 3, 'Which bin carries the largest Easy%Ro weight?', '["The 34 kcal bin, so that maturation starts promptly.", "The 72 kcal bin, so that reflectance never saturates.", "The 46 kcal bin, matching the Type II spectrum''s toe.", "The 52 kcal bin, at 0.07."]'::jsonb, 3, 'The most mass mid-ladder. The weights hump gently in the middle, peaking at 0.07 on 52 kcal, which is why reflectance keeps rising steadily through the oil window rather than exhausting early.'),
  ('basin', 'intermediate', 'module', 'm02-the-easy-ro-scheme', 4, 'What is F?', '["The fraction of bins that have fully emptied.", "The total reacted weight.", "The frequency factor divided by the gas constant.", "The unreacted weight remaining on the ladder."]'::jsonb, 1, 'Sum over bins of the initial weight minus what remains. F = sum(w_i - x_i). It is a state: every history that drains the ladder identically produces the same F, and the reflectance depends on F alone.'),
  ('basin', 'intermediate', 'module', 'm02-the-easy-ro-scheme', 5, 'The reflectance read-out is', '["Ro = 1.6 exp(-3.7 F).", "Ro = exp(-1.6 + 3.7 F).", "Ro = -1.6 + 3.7 F, in percent.", "Ro = exp(-1.6 F) + 3.7."]'::jsonb, 1, 'One line, no tables. F enters linearly in the exponent, so equal increments of reacted weight multiply reflectance by equal factors.'),
  ('basin', 'intermediate', 'module', 'm02-the-easy-ro-scheme', 6, 'Ro at zero reaction is', '["zero, since nothing has reacted yet at deposition.", "exactly 0.2, by convention.", "0.25, the lowest reflectance a laboratory can measure under oil immersion.", "exp(-1.6) = 0.20189651799465538, a closed form."]'::jsonb, 3, 'Set F = 0 and the formula gives exp(-1.6). It is graded to 0.001 and reachable on any calculator from the two published constants.'),
  ('basin', 'intermediate', 'module', 'm02-the-easy-ro-scheme', 7, 'Hand evaluation of exp(-1.6 + 3.7 x 0.85) gives 4.687971627022013, while the engine reports 4.687971627022019. Why?', '["The engine sums the twenty weights in floating point, landing on 0.8500000000000003.", "The engine adds a correction for the highest bin''s incomplete reaction.", "The oracle and the engine disagree at that digit, and the capstone stores the average of the two.", "Rounding in the constant 3.7."]'::jsonb, 0, 'The fifteenth-digit difference is summation order, not an error, and both values sit mid-tolerance. When hand and engine differ in the fifteenth digit, suspect arithmetic of summation, not physics.'),
  ('basin', 'intermediate', 'module', 'm02-the-easy-ro-scheme', 8, 'Every 0.1 of F multiplies the reflectance by', '["a factor that depends on where you start.", "exactly 1.37.", "e to the 0.37, about 1.448.", "e to the 0.1, about 1.105, the same step measured in F."]'::jsonb, 2, 'F is linear in the exponent, so equal F steps are equal multiplicative factors on Ro: exp(3.7 x 0.1) = 1.4477, wherever on the scale you apply it.'),
  ('basin', 'intermediate', 'module', 'm02-the-easy-ro-scheme', 9, 'Over one Ma at constant temperature, a bin holding fraction x becomes', '["x exp(-k dt), but only while k dt stays small.", "x (1 - k dt), the linear approximation the engine uses for small rates.", "x - k, clamped at zero.", "x exp(-k dt), with dt = 3.1536e13 seconds."]'::jsonb, 3, 'The step is exact for constant temperature at any step size: pure exponential decay per bin, with one Ma being 3.1536e13 seconds in the spec.'),
  ('basin', 'intermediate', 'module', 'm02-the-easy-ro-scheme', 10, 'At 100 degC the survival factors per Ma of the 46, 48 and 50 kcal bins are about 0.698, 0.976 and 0.998. The factor between adjacent bins'' rates is about', '["2, the doubling rule.", "5, the per-ten-degrees factor.", "15, from the 2 kcal spacing at that temperature.", "1526, the factor the same bin gains between 100 and 150 degC."]'::jsonb, 2, 'Adjacent bins differ by exp(2 x 4184 / (8.314 x 373.15)) = 14.84 at 100 degC. That spacing is why the reacting front is always only a couple of bins wide.'),
  ('basin', 'intermediate', 'module', 'm02-the-easy-ro-scheme', 11, 'Why does step size not matter when temperature is constant?', '["Because the engine automatically substeps to 0.01 Ma whatever step the caller requests, hiding the choice.", "Because exponential survival factors at one rate compose into a single exponential of total time.", "Because the bins are independent of each other.", "It does matter, but the error is inside tolerance."]'::jsonb, 1, 'exp(-k dt) applied n times equals exp(-k n dt) exactly. Only when temperature changes between steps do the factors stop merging, which is what the ramp convention manages.'),
  ('basin', 'intermediate', 'module', 'm02-the-easy-ro-scheme', 12, 'The pre-audit engine computed the exponent as E/(1.987 T) with E in kcal. The symptom was', '["every bin reacting instantly at any temperature above absolute zero.", "a 7 percent deficit at the graded ramp rows.", "gradual drift between the engine and the oracle.", "reflectance stuck at its floor value of 0.2019 for every history the engine was given."]'::jsonb, 0, 'R = 1.987 cal/(mol K) against E in kcal leaves a factor of 1000 in the exponent''s numerator. The exponent collapses toward zero, every rate becomes A itself, and all reactions complete in the first step.'),
  ('basin', 'intermediate', 'module', 'm02-the-easy-ro-scheme', 13, 'The defence that catches a units error in the exponent instantly is', '["asserting the two closed-form endpoint reflectances.", "comparing a full ramp against the independent Python oracle at 1e-9.", "halving the step size and re-running.", "code review of the constants."]'::jsonb, 0, 'A factor-of-1000 in the exponent moves every rate by many orders of magnitude, so the integrated endpoints land nowhere near 0.2019 and 4.688 and the anchor assertion fails on the first run. The other checks work but are slower or weaker.'),
  ('basin', 'intermediate', 'module', 'm02-the-easy-ro-scheme', 14, 'A rock at Ro 1.0 has F = 0.4324, which means', '["43 percent of the oil window remains.", "about half of the scheme''s total 0.85 weight has reacted.", "the rock''s reflectance is at 43 percent of the full-reaction value of 4.688.", "the 43rd percentile of measured samples."]'::jsonb, 1, 'Inverting the read-out, F = (ln Ro + 1.6)/3.7. At Ro 1.0 that is 0.4324, just over half of 0.85: the classic top of the oil window is a half-drained ladder.'),
  ('basin', 'intermediate', 'module', 'm02-the-easy-ro-scheme', 15, 'Why is the arithmetic average of two reflectances misleading?', '["The average of two states is not a state.", "Laboratory reflectances are medians, not means.", "Reflectance is exponential in F.", "It is fine; reflectance averages linearly."]'::jsonb, 2, 'The honest average is taken in F or as a geometric mean. Equal-looking Ro differences are very different amounts of reaction at different maturities. Averaging in F respects the state; averaging Ro overweights the higher value.'),
  ('basin', 'intermediate', 'module', 'm03-the-heating-ramp', 1, 'The golden ramp convention integrates each 0.01 Ma sub-step at', '["the temperature at the start of the sub-step.", "the temperature at the end of the sub-step.", "the midpoint temperature of the sub-step.", "the average of the whole ramp."]'::jsonb, 2, 'Midpoint evaluation cancels the first-order error. A start-point rule systematically under-reacts because the exponential rate always curls upward within the step.'),
  ('basin', 'intermediate', 'module', 'm03-the-heating-ramp', 2, 'How many sub-steps does the 3 degC per Ma ramp execute from 20 to 200 degC?', '["6000.", "18000.", "1800.", "600."]'::jsonb, 0, '180 degrees at 3 degC per Ma is 60 Ma, at 0.01 Ma per step 6000 steps. The 1 degC per Ma ramp takes 18000.'),
  ('basin', 'intermediate', 'module', 'm03-the-heating-ramp', 3, 'A start-of-step temperature rule on a heating ramp', '["matches the midpoint rule when steps are 0.01 Ma.", "systematically over-predicts maturity.", "produces random errors that average out.", "systematically under-predicts maturity."]'::jsonb, 3, 'Every step is evaluated at its coolest moment. The Arrhenius rate curves upward in temperature, so the start-point rate is always below the step''s true average and the deficits accumulate in one direction. A 7 percent deficit at rate 3 is its signature.'),
  ('basin', 'intermediate', 'module', 'm03-the-heating-ramp', 4, 'Ro at 150 degC on the 3 degC per Ma ramp is', '["1.1129254516555198.", "0.9871413464062039.", "0.8795791051334334.", "1.006902942398925."]'::jsonb, 1, 'The graded reference value, tolerance 0.002. The rate 1 value is 1.1129254516555198 and the rate 10 value is 0.8795791051334334; 1.0069 is the rate 1 ramp''s reading at 144 degC.'),
  ('basin', 'intermediate', 'module', 'm03-the-heating-ramp', 5, 'The 150 degC row of the rate 3 table represents', '["the equilibrium reflectance of 150 degC.", "the state of a rock that has been heating at that pace and has just passed 150 degC.", "the maximum reflectance any history reaching 150 degC can produce, whatever its pace.", "an interpolation between the 140 and 160 rows."]'::jsonb, 1, 'Nothing about the row is an equilibrium: hold the rock at 150 and Ro keeps rising slowly. The table records history, not a property of the temperature.'),
  ('basin', 'intermediate', 'module', 'm03-the-heating-ramp', 6, 'Compared at the same 150 degC, the 1 degC per Ma rock reads higher than the 3 degC per Ma rock because', '["slower heating lowers each bin''s activation energy.", "the slow rock ran hotter at every stage of its climb toward the shared 150 degC endpoint.", "the convention samples the slow ramp more finely.", "it spent three times as long at every temperature on the way."]'::jsonb, 3, 'Reaction is rate times residence. Both rocks passed through identical temperatures at identical rates of reaction. Only the residence per degree differs, and the slow rock collected three times as much of it.'),
  ('basin', 'intermediate', 'module', 'm03-the-heating-ramp', 7, 'The slow ramp reads 12.74 percent higher at 150 degC, not 200 percent higher, because', '["the ladder absorbs the extra time.", "the read-out compresses all gains logarithmically.", "the two ramps share 80 percent of their sub-steps.", "reaction saturates at F = 0.85."]'::jsonb, 0, 'Drained bins gain nothing and inert bins nearly nothing. Tripled residence only deepens the drain at the narrow reacting front. On a ladder of staggered exponentials, time acts roughly logarithmically at fixed temperature.'),
  ('basin', 'intermediate', 'module', 'm03-the-heating-ramp', 8, 'In which comparison does the FAST ramp give the higher reflectance?', '["At equal reacted weight.", "In no comparison; slower always wins.", "At equal elapsed time.", "At equal temperature."]'::jsonb, 2, 'At the same age the fast rock is far hotter, and heat beats time whenever they compete. At 43.333 Ma the rate 3 rock is at 150 degC reading 0.9871 while the rate 1 rock is at 63 degC, barely off the floor.'),
  ('basin', 'intermediate', 'module', 'm03-the-heating-ramp', 9, 'The first whole degree at which the rate 1, 3 and 10 ramps reach Ro 0.5 is', '["99, 92 and 86 degC.", "94, 100 and 107 degC.", "82, 82 and 82 degC.", "86, 92 and 99 degC."]'::jsonb, 3, 'The same threshold shifts about 13 degrees across a factor of ten in rate. The middle option is the Ro 0.55 row, and the last has the order reversed.'),
  ('basin', 'intermediate', 'module', 'm03-the-heating-ramp', 10, '"The oil window starts around 90 degC" is', '["true for Type II kerogen only.", "the definition of the window''s top.", "a rate-dependent statement.", "false; windows start near 120 degC."]'::jsonb, 2, 'Each heating rate crosses any Ro threshold at its own temperature. Ro 0.5 is crossed at 86, 92 or 99 degC depending on whether the rock heated at 1, 3 or 10 degC per Ma. A window quoted in degrees has silently fixed a heating rate.'),
  ('basin', 'intermediate', 'module', 'm03-the-heating-ramp', 11, 'With a 30 degC per km gradient and 20 degC surface, the Ro 1.0 boundary for rate 1 (144 degC) and rate 10 (159 degC) sits at depths of', '["4.8 and 5.3 km.", "4.13 and 4.63 km, half a kilometre apart on identical rocks.", "the same depth for both, since the rocks and their kinetic parameters are identical.", "3.1 and 3.6 km."]'::jsonb, 1, '(144 - 20)/30 = 4.13 km and (159 - 20)/30 = 4.63 km. Depth rules of thumb transplanted between basins with different subsidence histories miss by this kind of margin.'),
  ('basin', 'intermediate', 'module', 'm03-the-heating-ramp', 12, 'Order-of-magnitude uncertainty in heating rate moves every maturity boundary by about', '["13 to 15 degrees.", "40 degrees.", "1 to 2 degrees.", "nothing, if the kinetics are calibrated."]'::jsonb, 0, 'Each factor of about 3 in rate shifts the crossings 6 to 9 degrees, so a factor of 10 is worth roughly 13 to 15 degrees on every threshold.'),
  ('basin', 'intermediate', 'module', 'm03-the-heating-ramp', 13, 'The F decrements per factor-of-3 of rate at 150 degC are 0.0324 and 0.0312. This near-evenness means', '["logarithmic interpolation in rate between the fixture curves is trustworthy.", "rate uncertainty compounds quadratically, doubling with each factor of 3 in rate.", "the ramps converge at high temperature.", "F is linear in temperature."]'::jsonb, 0, 'Equal progress per multiplicative step of the driver is a logarithm. For a rock at 5 degC per Ma, interpolate between the rate 3 and rate 10 curves logarithmically and carry the bracket as the uncertainty.'),
  ('basin', 'intermediate', 'module', 'm03-the-heating-ramp', 14, 'Why does heating rate discriminate maturity most strongly in the oil window?', '["Because the window''s bins carry the largest published weights, 0.07 at 52 kcal.", "Because the mid-ladder bins are partially drained there.", "Because laboratory calibration concentrated there.", "Because the read-out is steepest there."]'::jsonb, 1, 'Their drain depth is set by residence time. Early bins finish at any geological rate and high bins barely start, so the rate effect concentrates where the front is actively draining, which is the window. At 60 degC the curves differ by half as much as at 150.'),
  ('basin', 'intermediate', 'module', 'm03-the-heating-ramp', 15, 'Estimate Ro at 150 degC for a rock heated at 30 degC per Ma.', '["About 0.88, the rate 10 value.", "About 0.99, the rate 3 value, since rate stops mattering once it exceeds 10 degC per Ma.", "About 0.78, one factor-of-3 decrement of F beyond the rate 10 curve.", "About 0.70, two decrements down."]'::jsonb, 2, 'From F = 0.39775 at rate 10, subtract the established 0.032 decrement: F near 0.3657, Ro = exp(-1.6 + 3.7 x 0.3657) = 0.781. The pattern is the instrument once the fixtures run out.'),
  ('basin', 'intermediate', 'module', 'm04-the-kerogen-clock', 1, 'The Type II kerogen potentials are nonzero from', '["34 kcal upward, sharing the vitrinite weights'' full grid.", "50 kcal upward, peaking at 62.", "46 kcal upward, peaking at 0.22 on the 54 kcal bin.", "44 kcal upward, peaking at 0.25 on the 52 kcal bin, the lacustrine shape."]'::jsonb, 2, 'Type II runs 0.01 at 46 up to a 0.22 peak at 54 and away to nothing above 64. The 44-peak-52 shape is Type I and the 50-peak-62 shape is Type III.'),
  ('basin', 'intermediate', 'module', 'm04-the-kerogen-clock', 2, 'The kerogen potentials sum to 1, unlike the vitrinite weights, so that', '["the transformation ratio is a true fraction of total potential.", "the two states can be added.", "the read-out formula exp(-1.6 + 3.7 F) applies to the kerogen state unchanged.", "every kerogen type ends up generating the same mass at full conversion."]'::jsonb, 0, 'TR = 1 - sum(x)/sum(x0) is the reacted fraction of the initial potential. The engine still divides by the sum, so a measured spectrum summing to 0.97 stays an honest fraction.'),
  ('basin', 'intermediate', 'module', 'm04-the-kerogen-clock', 3, 'The transformation ratio at 100 degC after 10 Ma, Type II, is', '["0.05477927380797565.", "0.20189651799465538, the reflectance floor.", "0.07419624543388115.", "0.022481215976523083."]'::jsonb, 3, 'The graded value, tolerance 0.0005. The 50 Ma value is 0.05477927380797565 and the ungraded 100 Ma value is 0.07419624543388115; 0.202 is the reflectance floor, a different clock entirely.'),
  ('basin', 'intermediate', 'module', 'm04-the-kerogen-clock', 4, 'The isothermal fixture uses whole-Ma steps because', '["the 0.01 Ma convention only applies below 100 degC.", "at constant temperature step size is irrelevant.", "the kerogen clock is less accurate than the vitrinite clock.", "whole steps are needed for the goldens'' table grid."]'::jsonb, 1, 'The exponentials compose exactly. There is no midpoint to choose when every midpoint is the same temperature, and n steps at one rate merge into one exponential of the total time.'),
  ('basin', 'intermediate', 'module', 'm04-the-kerogen-clock', 5, 'At 100 degC and 50 Ma, most of the Type II conversion has come from', '["the 54 kcal peak bin.", "the 46 and 48 kcal bins.", "an even drain across all occupied bins.", "the 50 and 52 kcal bins."]'::jsonb, 1, 'The toe of the spectrum, not its bulk. The 46 bin is fully consumed and the 48 bin seventy percent drained; together they carry most of the 0.0548. The 0.22-potential peak at 54 has lost 0.00008 of its content.'),
  ('basin', 'intermediate', 'module', 'm04-the-kerogen-clock', 6, 'Five times the time at 100 degC (10 to 50 Ma) buys 2.44x the conversion, and the next doubling buys 1.35x. This stall happens because', '["the transformation ratio is defined on a logarithmic scale.", "the potentials deplete uniformly toward zero.", "the temperature drifts down as the reaction consumes heat.", "each bin above the front is about fifteen times slower."]'::jsonb, 3, 'Waiting moves the front''s edge logarithmically. The toe burns off and the front then faces the next rung''s factor of fifteen. Isothermal TR is the low-energy tail burning; the high-energy bulk needs temperature, not patience.'),
  ('basin', 'intermediate', 'module', 'm04-the-kerogen-clock', 7, 'The practical ceiling for Type II conversion at 100 degC is set by', '["the 0.17 of potential at or below 50 kcal.", "the 0.85 unnormalised sum of the published vitrinite weights.", "the retention cap of the source layer at its present geometry.", "the duration of the basin''s history."]'::jsonb, 0, 'The front can reach. The front at 100 degC cannot pass the 50 kcal wall on geological timescales, and the occupancy at or below it is 0.01 + 0.05 + 0.11 = 0.17. TR 0.5 at 100 degC is unreachable at any duration.'),
  ('basin', 'intermediate', 'module', 'm04-the-kerogen-clock', 8, 'TR after 10 Ma at 80, 100, 120, 140 and 160 degC runs 0.00137, 0.0225, 0.111, 0.296, 0.556. The multipliers shrink with temperature because', '["conversion approaches its maximum of 1.", "the frequency factor falls with rising temperature, from 1e13 per second toward 1e12 across the walk.", "each warming step moves from unlocking untouched bins to finishing partly drained ones.", "the spectrum narrows as it drains."]'::jsonb, 2, 'Cold steps are near-multiplicative, unlocking bins from zero; hot steps are additive, finishing bins already reacting. The gains stay above 1 because higher bins always hold unreached potential.'),
  ('basin', 'intermediate', 'module', 'm04-the-kerogen-clock', 9, 'Twenty degrees of warming at 10 Ma (100 to 120 degC) bought a factor of 4.9 in conversion. Forty extra Ma at 100 degC bought', '["a factor of about 12, time being the stronger lever in this range.", "a factor of 4.9 as well.", "nothing measurable.", "a factor of 2.44, half as much for five times the duration."]'::jsonb, 3, 'The graded pair: 0.0225 to 0.0548 for the 40 Ma wait, against 0.0225 to 0.111 for the 20 degree step. In this part of the ladder, twenty degrees outbuys a factor of five of time.'),
  ('basin', 'intermediate', 'module', 'm04-the-kerogen-clock', 10, 'At 100 degC and 50 Ma, the conversion of Types I, II and III spans', '["a factor of 3 at most, since they share the energy grid.", "0.498 / 0.298 / 0.0347, a factor of 14 between Types I and III.", "0.129 / 0.0548 / 0.00097, a factor of 132 between I and III.", "identical values, since A is the same."]'::jsonb, 2, 'Same history, same thermometer, two orders of magnitude of spread from the spectra alone. The 0.498 row is the same comparison at 130 degC, where the spread collapses to 14.'),
  ('basin', 'intermediate', 'module', 'm04-the-kerogen-clock', 11, 'The type spread narrows from 132x at 100 degC to 14x at 130 degC because', '["Type III''s frequency factor rises with temperature.", "heat drives the front into every spectrum''s bulk.", "Type I exhausts its potential first.", "the comparison durations differ."]'::jsonb, 1, 'Types differ in schedule rather than fate. Hotter histories reach every spectrum''s occupied bins. Type III is not a rock that will not generate; it is a rock that generates deeper and later, hence terrestrial kerogen as the gas source of deep basins.'),
  ('basin', 'intermediate', 'module', 'm04-the-kerogen-clock', 12, 'Switching kerogen type in the panel moves', '["the transformation curve only; every reflectance stays fixed to the last digit.", "neither curve, only the tiles.", "the reflectance curves only.", "both the transformation curve and the reflectance curves, each scaled by its spectrum."]'::jsonb, 0, 'Ro belongs to the vitrinite clock, whose parameters no kerogen edit reaches. Performing this switch deliberately is the diagnostic for the documented conflation defect.'),
  ('basin', 'intermediate', 'module', 'm04-the-kerogen-clock', 13, 'A review reads: "Type III source, regional Ro 0.7, so early mature and expelling oil." The errors are', '["using maturity as conversion despite Type III''s high spectrum.", "none; the chain is sound.", "only the maturity call, since Ro 0.7 is barely inside the window.", "Type III cannot coexist with Ro 0.7."]'::jsonb, 0, 'Calling the products oil. At histories giving Ro 0.7 the front sits near 50 kcal, where Type III holds almost nothing, so TR is of order a percent; and what Type III does convert is gas prone. Maturity is not conversion, and the spectrum decides the products.'),
  ('basin', 'intermediate', 'module', 'm04-the-kerogen-clock', 14, 'A TR of 0.3 becomes a mass of hydrocarbon by', '["multiplying by the vitrinite F.", "multiplying by the source''s generative potential.", "integrating the spectrum a second time.", "no route; TR is dimensionless and remains so at every tier of the ladder."]'::jsonb, 1, 'Is the Expert tier''s job. TR is the fraction of potential converted. Mass needs richness, thickness and density, none of which the kinetics know, and the tier above multiplies them in.'),
  ('basin', 'intermediate', 'module', 'm04-the-kerogen-clock', 15, 'The hand route to the 10 Ma graded value sums contributions from bins', '["34 through 44, the empty toe.", "all twenty of the bins, or the answer misses its 0.0005 grading tolerance.", "46 through 52, reproducing 0.02248 to within 0.07 percent.", "54 only, the peak."]'::jsonb, 2, 'Four bins do it: 0.0097264 + 0.010767 + 0.0017829 + 0.00019 = 0.0224663, within 0.07 percent of 0.022481215976523083 and comfortably inside the 0.0005 tolerance.'),
  ('basin', 'intermediate', 'module', 'm05-reading-a-maturity', 1, 'What part of the oil window idea is physical rather than conventional?', '["The edge values 0.55 and 1.3.", "The temperatures at which the window is entered on the reference 3 degC per Ma ramp.", "The kinetic ordering: immature, then oil generation, then cracking toward gas.", "The depths assigned to the window in a basin whose geothermal gradient has been measured."]'::jsonb, 2, 'The ordering is universal kinetics. The edges are drawn by convention and differ by author; the temperatures and depths depend on heating rate and gradient.'),
  ('basin', 'intermediate', 'module', 'm05-reading-a-maturity', 2, 'Two documents use window edges 0.6-1.2 and 0.5-1.35. To compare their maturity claims,', '["convert everything to F with (ln Ro + 1.6)/3.7 and compare states.", "average the two conventions'' edges into a compromise window of 0.55 to 1.28.", "adopt the wider of the two windows as the more conservative reading.", "reject the document with nonstandard edges."]'::jsonb, 0, 'F is the invariant state under any convention. The rulers differ; the rock does not, and the conversion makes agreement or disagreement visible immediately.'),
  ('basin', 'intermediate', 'module', 'm05-reading-a-maturity', 3, 'The F values of window edges Ro 0.55 and Ro 1.3 are about', '["0.43 and 0.85.", "0.55 and 1.30, unchanged, because the reflectance scale and the F scale coincide inside the window.", "0.10 and 0.90.", "0.27 and 0.50: the window spans the middle quarter-to-half of the ladder''s weight."]'::jsonb, 3, 'F = (ln 0.55 + 1.6)/3.7 = 0.2709 and (ln 1.3 + 1.6)/3.7 = 0.5033. About a quarter of the reacted weight enters the window and another quarter exits it.'),
  ('basin', 'intermediate', 'module', 'm05-reading-a-maturity', 4, 'A window position ("mid oil window") never carries', '["the reflectance value it corresponds to.", "the temperature and depth of its edges.", "any kinetic content.", "the ordering relative to the gas window, which depends on the author''s convention."]'::jsonb, 1, 'The converted fraction of the source. Temperature and depth depend on the heating rate; converted fraction depends on the kerogen spectrum. The window summarises the vitrinite state and nothing else.'),
  ('basin', 'intermediate', 'module', 'm05-reading-a-maturity', 5, 'A measured Ro of 0.99 is consistent with', '["only one temperature history.", "reaching 150 degC at 3 degC per Ma, or 144 degC at 1 degC per Ma.", "temperatures that never exceeded 150 degC at any moment of the history.", "a unique maximum temperature, provided the Easy%Ro kinetics are calibrated against the oracle."]'::jsonb, 1, 'Many histories. Many histories drain a ladder equally: the graded 0.9871 at 150/rate 3 sits beside 1.0069 at 144/rate 1. Reflectance constrains histories, never instants.'),
  ('basin', 'intermediate', 'module', 'm05-reading-a-maturity', 6, 'Ro answers "what history has this rock had". The question "what did that history generate" is answered by', '["the window convention in force, applied to the measured Ro.", "the same Ro, scaled by the source''s TOC and hydrogen index.", "the crossing table.", "the kerogen clock, fed the same history and a spectrum."]'::jsonb, 3, 'The vitrinite clock knows nothing of the source''s chemistry. Yield requires the kerogen state, and even that is not charge until mass and expulsion enter, one tier up.'),
  ('basin', 'intermediate', 'module', 'm05-reading-a-maturity', 7, 'Reflectance is a ratchet: it parks at its historical maximum. As an instrument, this means', '["an Ro too high for the present depth and gradient is evidence of a hotter or deeper past.", "present-day Ro always matches the present-day temperature once a heating rate has been assumed.", "cooling episodes can be read directly from Ro logs.", "Ro dates its own acquisition."]'::jsonb, 0, 'The maximum survives uplift and cooling. Quantifying the excess against the preserved section''s history is how the Expert tier reads the reference basin''s missing 600 metres.'),
  ('basin', 'intermediate', 'module', 'm05-reading-a-maturity', 8, 'A wellsite note says: "Ro 1.1 at 3200 m; present gradient gives 118 degC; so the section reached 118 degC." The correct reading is', '["confirmed, since 118 degC matches Ro 1.1.", "the gradient must be wrong.", "the rock has been hotter than today.", "Ro 1.1 is impossible at 3200 m."]'::jsonb, 2, 'Plausible rates put Ro 1.1''s acquisition at 155 to 170 degC. F = 0.4581 at Ro 1.1 needs temperatures well above 118 on any plausible rate. The rock''s thermometer reads today; its odometer reads the past, and here they disagree informatively.'),
  ('basin', 'intermediate', 'module', 'm05-reading-a-maturity', 9, 'Skipping decompaction when building a burial history biases maturity', '["randomly, averaging out across a basin.", "upward, since thinner layers conduct heat upward faster and run hotter through the early history.", "not at all, if present depths are honoured.", "downward everywhere: every old layer sits too shallow and too cool through the early history."]'::jsonb, 3, 'Compaction always thins with depth, so the error has one sign basin-wide: under-buried, under-heated, under-matured. Systematic errors do not average out.'),
  ('basin', 'intermediate', 'module', 'm05-reading-a-maturity', 10, 'A persistent 300 m under-burial under a 30 degC/km gradient costs about', '["90 degC of history.", "9 degC, which the tolerance absorbs.", "9 degC of history, roughly a factor of 2 in conversion and a band of reflectance.", "nothing, provided the heat flow was calibrated against the well''s measured reflectance."]'::jsonb, 2, 'Nine degrees at the front is most of a factor-of-five-per-ten rate change sustained through the whole history: expect TR understated by about half and Ro reading a band low.'),
  ('basin', 'intermediate', 'module', 'm05-reading-a-maturity', 11, 'Compensating a geometry error by raising heat flow until the calibration well fits', '["is standard practice and harmless.", "corrupts timing everywhere and mis-predicts every location whose geometry error differs from the calibration well''s.", "cancels the error everywhere in the basin.", "fails at the well but works regionally."]'::jsonb, 1, 'Two errors cancel at one well and disagree elsewhere, and the compensated model reaches every maturity state at wrong dates. The honest fix is upstream, in the geometry.'),
  ('basin', 'intermediate', 'module', 'm05-reading-a-maturity', 12, 'The first sanity check on any Easy%Ro implementation is', '["the two closed-form anchors.", "a full oracle comparison.", "monotonicity along a test ramp.", "the crossing table."]'::jsonb, 0, 'Exp(-1.6) and exp(-1.6 + 3.7 x 0.85). Thirty seconds of calculator arithmetic that catastrophic failures cannot pass. The other checks follow, in rising cost.'),
  ('basin', 'intermediate', 'module', 'm05-reading-a-maturity', 13, 'Which observation would prove an integrator bug rather than a parameter issue?', '["Ro dipping downward along a monotone heating history.", "Ro of 4.2 late in a very hot history.", "TR of 0.9 for a Type I kerogen late in a very hot history.", "The slow ramp reading above the fast one."]'::jsonb, 0, 'The state can only drain and the read-out is monotone in F, so a dip is mechanically impossible in a correct implementation. The other three are all legitimate outcomes.'),
  ('basin', 'intermediate', 'module', 'm05-reading-a-maturity', 14, 'An implementation passes both anchors exactly but reads 0.912 at the rate 3, 150 degC row. The likeliest cause is', '["a corrupted weight table.", "the integration convention.", "a units error in the exponent.", "an oracle disagreement."]'::jsonb, 1, 'Step size or a start-of-step temperature rule. Anchors clear the constants and read-out; a 7 percent deficit at a ramp row is the signature of systematic under-reaction within steps, exactly what start-point evaluation produces.'),
  ('basin', 'intermediate', 'module', 'm05-reading-a-maturity', 15, 'The engine and the independent Python oracle agree to about', '["1e-15, bit-for-bit.", "1e-2, which every graded tolerance is wide enough to absorb.", "1e-9 on kinetics, far tighter than any graded tolerance.", "they are the same code, so exactly."]'::jsonb, 2, 'Two independent implementations agreeing to 1e-9 is the fixtures'' warrant. Your tolerance is orders of magnitude wider, so an answer outside it is your arithmetic, never the fixture.'),
  ('basin', 'intermediate', 'module', 'm06-the-kinetics-workflow', 1, 'The first step of the kinetics workflow is', '["fixing the temperature track and its pace.", "choosing the step size.", "naming which clock answers the question.", "running the sanity checks on the machinery."]'::jsonb, 2, 'That fixes the parameter obligations. Calibration questions take the vitrinite clock and its fixed constants; yield questions take the kerogen clock and oblige you to state whose spectrum. Everything downstream depends on that naming.'),
  ('basin', 'intermediate', 'module', 'm06-the-kinetics-workflow', 2, 'When the heating rate of a history is uncertain, the workflow says', '["bracket it, and carry the bracket.", "use 3 degC per Ma, the reference rate of the fixtures.", "average the candidate rates.", "the rate does not matter for reflectance."]'::jsonb, 0, 'About 13 degrees per factor of 3 on every boundary. Rate uncertainty propagates to every threshold''s temperature. The bracket is the honest error bar, and module 3''s family is how you evaluate it.'),
  ('basin', 'intermediate', 'module', 'm06-the-kinetics-workflow', 3, 'The conventions of step three (integrate) are', '["whatever the software defaults to.", "adaptive stepping, with the error tolerance set to the 1e-9 oracle agreement level.", "1 Ma steps everywhere.", "0.01 Ma midpoint sub-steps on ramps, whole-Ma steps at constant temperature."]'::jsonb, 3, 'The fixture conventions. They are not decoration: a wrong step rule alone produced a 7 percent error in the diagnosed example.'),
  ('basin', 'intermediate', 'module', 'm06-the-kinetics-workflow', 4, 'A reported reflectance should travel with', '["its laboratory certificate.", "its heating assumption.", "the raw bin states.", "nothing; a reflectance is a self-contained laboratory observable."]'::jsonb, 1, 'A TR with its spectrum named. Ro''s meaning in temperature and depth is rate-dependent, and TR''s meaning is spectrum-dependent. A number without its assumption cannot be compared, mapped or checked.'),
  ('basin', 'intermediate', 'module', 'm06-the-kinetics-workflow', 5, 'On the capstone, the two anchor fields skip which workflow steps?', '["Step one: the clock is ambiguous.", "Steps two and three: their F values are endpoints known without any integration.", "None; all six of the fields need the full five-step workflow, the anchors included.", "Step five: anchors need no checks."]'::jsonb, 1, 'F = 0 and F = 0.85 need no history and no integrator, just the read-out. They are graded precisely because they prove you know the scheme''s closed forms.'),
  ('basin', 'intermediate', 'module', 'm06-the-kinetics-workflow', 6, 'Which is a correct one-line run record?', '["\"Ro 0.99 at the source.\"", "\"Kinetics fine, see model.\"", "\"Run 47 complete, results in the shared project folder, all of the usual checks passed as before.\"", "\"Vitrinite, 20 to 150 at 3 degC per Ma, midpoint 0.01 Ma, anchors and row-150 verified.\""]'::jsonb, 3, 'Ro 0.9871.". Clock, track with pace, convention, checks passed, answer. That sentence is auditable a year later; the others are not records.'),
  ('basin', 'intermediate', 'module', 'm06-the-kinetics-workflow', 7, 'QC interrogates three things, in order:', '["the inputs, the software.", "the answer, the reviewer, and the deadline.", "the oracle, the engine, and the panel.", "the spectrum, the weights, and the constants."]'::jsonb, 0, 'The answer itself. Where did the history come from; has this machinery passed the five checks; and does the answer sit right against range, direction and magnitude landmarks.'),
  ('basin', 'intermediate', 'module', 'm06-the-kinetics-workflow', 8, 'A deliverable pairs Ro 1.05 with a Type III TR of 62 percent. QC flags it because', '["Ro 1.05 is outside the oil window.", "62 percent is impossible for any kerogen.", "the pair is internally inconsistent: a Type III spectrum at Ro 1.05 histories sits far below 62 percent.", "the TOC is missing."]'::jsonb, 2, 'Ro 1.05 fixes the history''s reach on the ladder; Type III''s bulk sits above it, and the type-spread arithmetic prices its TR at a small fraction of the claim. Pairings are checkable even when each number alone looks plausible.'),
  ('basin', 'intermediate', 'module', 'm06-the-kinetics-workflow', 9, 'An unstated kerogen type in a yield claim is', '["a style issue.", "acceptable so long as the TOC and hydrogen index are stated.", "recoverable from the reflectance through the crossing table.", "up to two orders of magnitude of hidden uncertainty."]'::jsonb, 3, 'The type spread at cool histories is a factor of 132. A yield without its spectrum named is not an answer, and no reflectance can recover the spectrum.'),
  ('basin', 'intermediate', 'module', 'm06-the-kinetics-workflow', 10, 'The software convergence check is', '["running the anchors twice.", "comparing two machines.", "a graded row at the standard step, then at half the step, confirming movement inside tolerance.", "increasing the temperature control until the reflectance stabilises at its full-reaction ceiling of 4.688."]'::jsonb, 2, 'Demonstrated convergence beats promised convergence. On ramps the step interacts with the temperature rule, so this check exercises both.'),
  ('basin', 'intermediate', 'module', 'm06-the-kinetics-workflow', 11, 'The capstone''s ramp fields are answered by', '["interpolating the crossing table between the Ro 0.5 and Ro 1.0 rows.", "the golden tables'' 150 degC rows for rates 3 and 1.", "the anchors scaled by F.", "the panel''s TR tiles."]'::jsonb, 1, '0.9871413464062039 and 1.1129254516555198, tolerance 0.002 each. Panel, table or your own midpoint integrator all land there; the TR tiles belong to the other clock.'),
  ('basin', 'intermediate', 'module', 'm06-the-kinetics-workflow', 12, 'Which habit does the workflow lesson say to carry into the Expert tier?', '["State the heating pace, keep the clocks separate.", "Prefer steady heat models for speed.", "Normalise F before reporting.", "Average reflectances across horizons before calibrating."]'::jsonb, 0, 'Remember the stall through long cooling eras. The Expert basin spends 76 Ma cooling, multiplies one clock by a mass and calibrates against the other. All three habits are load-bearing there.'),
  ('basin', 'intermediate', 'module', 'm06-the-kinetics-workflow', 13, 'The workflow''s deliverable sentence for a field task includes', '["the spectrum, the track with its bracket.", "only the final number, for the reader''s clarity.", "the software version and license.", "every bin''s final state."]'::jsonb, 0, 'The answer with its uncertainty. "Type II library kinetics on an 8 degC per Ma ramp to 113 degC give early conversion, of order a few percent, bracketed by rates 5 to 10." Assumptions travel with answers.'),
  ('basin', 'intermediate', 'module', 'm06-the-kinetics-workflow', 14, 'Why does the tier insist every number in a lesson be derivable?', '["Because derived numbers always carry more significant figures than quoted ones do.", "Because a value you can re-derive is one you can check, defend and correct.", "So the fixtures can be regenerated.", "To match the oracle''s output format."]'::jsonb, 1, 'The course''s discipline: closed forms by hand, ramp rows by convention, TR by bin arithmetic. The capstone rewards routes, and real work rewards nothing else.'),
  ('basin', 'intermediate', 'module', 'm06-the-kinetics-workflow', 15, 'The kinetics tier''s boundary with the tier above is', '["the energy grid, which changes above.", "reflectance: the Expert tier replaces Easy%Ro with a per-basin calibrated scheme.", "mass and history: nothing here produces kilograms or its own temperature track.", "there is no boundary; the tiers overlap."]'::jsonb, 2, 'This tier consumes given histories and produces dimensionless state. The Expert tier generates the histories from a forward model and multiplies TR into generated and expelled mass.'),
  ('basin', 'intermediate', 'final', null, 1, 'A rock''s history is a track of temperatures. The tier''s two clocks turn it into', '["two reflectances, one per state.", "a temperature and a depth.", "a reflectance from the vitrinite state and a transformation ratio from the kerogen state.", "a cumulative mass of hydrocarbon generated and a cumulative mass expelled, per square metre of basin."]'::jsonb, 2, 'One integrator, two states, two read-outs. Masses belong to the Expert tier.'),
  ('basin', 'intermediate', 'final', null, 2, 'The Easy%Ro frequency factor is', '["1e13 per second, fixed for all twenty vitrinite bins.", "1e13 per Ma.", "fitted per basin during calibration, within published bounds.", "2 kcal/mol."]'::jsonb, 0, 'A = 1e13 1/s, one value, never edited. The kerogen clock defaults to the same value but allows a per-type override.'),
  ('basin', 'intermediate', 'final', null, 3, 'Which list is the vitrinite weights'' defining property set?', '["Sum 1, editable, with the peak at 54 kcal, matching Type II.", "Sum 1, fixed for all basins, with the weights uniform across the twenty bins.", "Sum 0.85, editable per basin.", "Sum 0.85, fixed, gentle mid-ladder hump peaking at 52 kcal."]'::jsonb, 3, 'Published, fixed, summing to 0.85 with the 0.07 peak on 52 kcal. The read-out is calibrated on the unnormalised scale.'),
  ('basin', 'intermediate', 'final', null, 4, 'Ro at full reaction, as the engine computes it, is', '["4.7 exactly.", "4.687971627022019.", "0.20189651799465538.", "5.0, the scheme''s ceiling."]'::jsonb, 1, 'exp(-1.6 + 3.7 x 0.85) with the weights summed in floating point. 0.2019 is the other anchor, the floor.'),
  ('basin', 'intermediate', 'final', null, 5, 'A history leaves F = 0.3. The reflectance is', '["0.3 x 4.688 = 1.406, scaling the ceiling.", "exp(-1.6 + 3.7 x 0.3) = 0.6126.", "exp(-0.3) = 0.741.", "0.2019 + 0.3 = 0.502, the floor plus the reacted weight."]'::jsonb, 1, 'The read-out is the single exponential map. Neither scaling the ceiling nor adding to the floor is the formula.'),
  ('basin', 'intermediate', 'final', null, 6, 'What F corresponds to a measured Ro of 2.0?', '["0.85; any Ro that high is full reaction.", "0.54, the reacted weight halfway to the ceiling.", "0.43.", "(ln 2 + 1.6)/3.7 = 0.6198."]'::jsonb, 3, 'Invert the read-out. About 73 percent of the way to full reaction; 0.43 is Ro 1.0''s F.'),
  ('basin', 'intermediate', 'final', null, 7, 'The kinetic step advances a bin by', '["multiplying by exp(-k dt).", "subtracting k dt from the fraction.", "transferring the reacted weight upward to the next bin on the energy ladder.", "multiplying by (1 - k) per Ma."]'::jsonb, 0, 'Bin independent of the others. Pure independent exponential decay per bin. Nothing couples the bins; the ensemble behaviour comes from the staggered energies.'),
  ('basin', 'intermediate', 'final', null, 8, 'The number of seconds in one Ma, as the spec pins it, is', '["3.6e13.", "3.15576e13, from a Julian year.", "3.1536e13, from a 365-day year.", "1e13, matching the frequency factor."]'::jsonb, 2, '1e6 x 365 x 86400 = 3.1536e13 exactly, and the oracle uses the same value, which matters at 1e-9 agreement.'),
  ('basin', 'intermediate', 'final', null, 9, 'The pre-G7 units bug made every bin react instantly because', '["A was 1e16 instead of 1e13.", "the time step used years instead of seconds, inflating every dt in the exponent by a factor of 3.15e7.", "temperatures were in Fahrenheit.", "E in kcal was divided by R in cal, leaving a factor of 1000 in the exponent''s numerator."]'::jsonb, 3, 'The exponent collapsed toward zero, so every rate became A itself. Unit errors in exponents destroy answers rather than degrading them.'),
  ('basin', 'intermediate', 'final', null, 10, 'At 100 degC the 48 kcal bin''s survival factor is 0.97604 per Ma. After 50 Ma it retains', '["about 0.02, the reacted complement of the survival.", "about 0.51.", "0.976 to the 50th power, about 0.298.", "0.976 regardless of duration; survival factors do not compound."]'::jsonb, 2, 'exp(-50 x 0.024251) = 0.2977. From its 0.05 potential that is 0.0351 reacted, the dominant term in the 50 Ma graded TR.'),
  ('basin', 'intermediate', 'final', null, 11, 'The ramp tables report Ro at', '["every 0.01 Ma sub-step of the integration, 6000 rows for rate 3.", "every whole degree, written when the ramp first reaches it.", "every 10 degrees.", "only the graded temperatures, one 150 degC row for each of the three rates."]'::jsonb, 1, 'Whole-degree reporting is the third piece of the convention, after 0.01 Ma sub-steps and midpoint evaluation.'),
  ('basin', 'intermediate', 'final', null, 12, 'The 1 degC per Ma ramp reaches 150 degC after', '["130 Ma and 13000 sub-steps.", "43.333 Ma, the same as the rate 3 ramp.", "13 Ma.", "150 Ma, one megayear per degree from absolute zero."]'::jsonb, 0, '(150 - 20)/1 = 130 Ma at 0.01 Ma per step. The rate 3 ramp takes 43.333 Ma and rate 10 takes 13.'),
  ('basin', 'intermediate', 'final', null, 13, 'Ro at 150 degC on the 1 degC per Ma ramp is', '["1.1129254516555198.", "0.9871413464062039.", "0.8795791051334334.", "1.3021395483097562."]'::jsonb, 0, 'The slow ramp''s graded value. The 0.9871 is rate 3, the 0.8796 rate 10, and 1.302 is the rate 10 ramp''s reading at 177 degC.'),
  ('basin', 'intermediate', 'final', null, 14, 'The percentage gap between the rate 1 and rate 3 readings at 150 degC is', '["2 percent.", "12.74 percent.", "33 percent.", "300 percent."]'::jsonb, 1, '1.1129254516555198 / 0.9871413464062039 = 1.1274. Three times the residence bought 12.74 percent of reflectance, the ladder absorbing the rest.'),
  ('basin', 'intermediate', 'final', null, 15, '"Slower heating means higher maturity" is', '["always true.", "false; the heating rate never changes where a maturity threshold falls.", "true at equal temperature and false at equal time.", "true only for Type II kerogen and the library spectra."]'::jsonb, 2, 'At the same temperature the slow rock wins on residence. At the same age the fast rock is hotter and wins outright, heat beating time whenever they compete.'),
  ('basin', 'intermediate', 'final', null, 16, 'The rate 3 ramp first reaches Ro 1.0 at', '["150 degC.", "144 degC.", "159 degC.", "151 degC."]'::jsonb, 3, 'The crossing table: 144 / 151 / 159 for rates 1 / 3 / 10. The graded 150 degC reading, 0.9871, sits one degree short of the crossing.'),
  ('basin', 'intermediate', 'final', null, 17, 'A maturity boundary quoted as a temperature has silently fixed', '["a surface temperature.", "a kerogen type.", "a heating rate.", "a step size."]'::jsonb, 2, 'Each rate crosses any threshold at its own temperature, 13 to 15 degrees apart across a factor of ten in rate. Within one basin the habit can be harmless; across basins it is an error.'),
  ('basin', 'intermediate', 'final', null, 18, 'Per factor-of-3 of heating rate, F at 150 degC falls by', '["about 0.32.", "about 0.032, nearly evenly.", "a factor of 3, mirroring the rate step.", "an amount that grows rapidly with rate."]'::jsonb, 1, 'Licenses logarithmic interpolation in rate. 0.46135 to 0.42893 to 0.39775: decrements 0.0324 and 0.0312. Equal progress per multiplicative step is a logarithm, and the evenness is what makes interpolation trustworthy.'),
  ('basin', 'intermediate', 'final', null, 19, 'For a rock heated at about 5 degC per Ma, its 150 degC reflectance is best estimated as', '["not estimable without a new fixture.", "the rate 3 value, since 5 rounds to the nearest fixture.", "the average of all three fixtures.", "near the middle of the rate 3 and rate 10 values."]'::jsonb, 3, '0.93, with the bracket as the uncertainty. Five is close to the geometric mean of 3 and 10, so interpolate logarithmically between 0.9871 and 0.8796 and carry the bracket width, about 0.11, as the rate-uncertainty error bar.'),
  ('basin', 'intermediate', 'final', null, 20, 'Heating-rate uncertainty matters least when deciding', '["whether a rock is barely mature versus immature at low temperature.", "where the oil window''s base sits on the depth axis of a calibrated well.", "the depth of the Ro 1.0 crossing in a calibrated basin.", "mid-window maturity."]'::jsonb, 0, 'At 60 degC the three curves differ by half their 150 degC spread: the early bins finish at any geological rate. Discrimination concentrates in the mid-ladder, the window.'),
  ('basin', 'intermediate', 'final', null, 21, 'The Type II spectrum''s first occupied bin, and its share, are', '["34 kcal with 0.03.", "46 kcal with 0.01, which is why early Type II generation is real but slight.", "50 kcal with 0.11.", "54 kcal with 0.22, the bin that carries both the spectrum''s peak and the bulk of its mass."]'::jsonb, 1, 'The toe is tiny. The 54 kcal bin holds the 0.22 peak, and nothing sits below 46.'),
  ('basin', 'intermediate', 'final', null, 22, 'TR at 100 degC after 50 Ma, Type II, is', '["0.5477927380797565.", "0.022481215976523083.", "0.05477927380797565.", "0.17."]'::jsonb, 2, 'The graded 50 Ma value. The 10 Ma value is 0.02248; 0.5478 is a factor-of-ten misread, and 0.17 is the theoretical 100 degC ceiling, not a computed TR.'),
  ('basin', 'intermediate', 'final', null, 23, 'The 100 Ma isothermal value 0.0742 shows that doubling the time from 50 Ma bought a factor of', '["1.35, the stall in one number.", "2.0, matching the doubling of the time.", "5.0, matching the five-fold time span of the first interval.", "0.5."]'::jsonb, 0, '0.07419624543388115 / 0.05477927380797565 = 1.3545. Waiting acts logarithmically once the toe is drained.'),
  ('basin', 'intermediate', 'final', null, 24, 'At 100 degC and 50 Ma the 46 kcal bin has reacted 0.00999999984675959 of its 0.01 potential, meaning', '["the bin''s weight was mis-set.", "the bin is at half life.", "the computation lost precision at the ninth digit.", "the bin is finished to nine digits."]'::jsonb, 3, 'Further time gains nothing from it. Drained bins are the stall''s floor: extra time cannot re-drain them, and the front faces the next rung''s factor of fifteen.'),
  ('basin', 'intermediate', 'final', null, 25, 'A Permian source parked at 95 degC for 250 Ma is best described as', '["impossible to assess without the basin''s complete heat-flow history and burial track.", "fully cooked by age.", "at the base of its oil window after so long a residence.", "barely converted: patience does not substitute for burial on a kinetic ladder."]'::jsonb, 3, 'At 95 degC the front sits below even the fixture''s, and time acts logarithmically. A kilometre of extra burial would outdo the entire wait.'),
  ('basin', 'intermediate', 'final', null, 26, 'Twenty degrees of warming versus forty extra megayears, both starting from 10 Ma at 100 degC:', '["the warming wins, 4.9x against 2.44x.", "the time wins.", "they are equal by construction of the fixtures.", "neither moves TR, which is already stalled at that state."]'::jsonb, 0, 'The graded comparisons: 100 to 120 degC at 10 Ma is a factor of 4.926, while 10 to 50 Ma at 100 degC is 2.4367.'),
  ('basin', 'intermediate', 'final', null, 27, 'The conversion ranking of the three types on any shared cool history is', '["II above I above III.", "III above II above I.", "I above II above III, from the spectra''s positions on the energy grid.", "identical, because the frequency factor and the activation energy grid are shared."]'::jsonb, 2, 'Peaks at 52, 54 and 62 kcal. Lower spectra react first; at 100 degC and 50 Ma the spread is a factor of 132 from I to III.'),
  ('basin', 'intermediate', 'final', null, 28, 'At hot histories the type spread collapses because', '["the three spectra converge toward a common shape.", "the front reaches every spectrum''s bulk.", "Type III''s A rises.", "the read-out saturates at its full-reaction ceiling."]'::jsonb, 1, 'Types differ in schedule rather than fate. 132x at 100 degC becomes 14x at 130. Type III generates late and deep, not never, which is why it is the deep-basin gas source.'),
  ('basin', 'intermediate', 'final', null, 29, 'A rock at Ro 0.9 sits at F = 0.404. As a fraction of full reaction that is', '["47.5 percent, just under half the ladder''s weight.", "40.4 percent, reading the F value directly as the fraction.", "90 percent.", "9 percent."]'::jsonb, 0, '0.40396 / 0.85 = 0.4752. The F scale, not the Ro scale, is where fractions of progress mean what they appear to mean.'),
  ('basin', 'intermediate', 'final', null, 30, 'The two clocks share', '["their editing policy, both being fixed published data.", "their weights.", "their read-outs, both mapping a reacted fraction to a percentage.", "the integrator and the energy grid."]'::jsonb, 3, 'Nothing else that matters. Same kineticStep, same 34-72 grid. Weights versus potentials, Ro versus TR, fixed versus editable: everything else is deliberately separate.'),
  ('basin', 'intermediate', 'final', null, 31, 'A model whose reported reflectance moved when TOC was edited would be', '["correctly coupling source richness into the maturity estimate.", "broken: TOC belongs to mass bookkeeping.", "using the oracle convention.", "acceptable within tolerance."]'::jsonb, 1, 'No reflectance path may touch. TOC is not even a kinetics input; it scales potential into mass one tier up. Any reflectance sensitivity to it means wires are crossed somewhere.'),
  ('basin', 'intermediate', 'final', null, 32, 'The window edges Ro 0.5 to 0.7 span F values', '["0.05 to 0.07.", "0.5 to 0.7.", "0.245 to 0.336.", "0.336 to 0.503."]'::jsonb, 2, '(ln 0.5 + 1.6)/3.7 = 0.2451 and (ln 0.7 + 1.6)/3.7 = 0.3360. The 0.336-0.503 span belongs to edges 0.7 to 1.3.'),
  ('basin', 'intermediate', 'final', null, 33, 'Which claim about a single measured Ro value is defensible?', '["It gives the source''s converted fraction.", "It gives the rock''s maximum temperature, read through the crossing table''s rows.", "It constrains the family of temperature histories the rock may have had.", "It dates the maturation."]'::jsonb, 2, 'One number, one state, many histories. Temperature needs a rate assumption, conversion needs the spectrum, and dating needs profiles or forward models.'),
  ('basin', 'intermediate', 'final', null, 34, 'The reflectance ratchet means a basin''s Ro log records', '["the average temperature of the history at each depth.", "present-day temperatures.", "the most recent heating event only, all older episodes being overprinted by it.", "the thermal maximum of each depth''s history."]'::jsonb, 3, 'It occurred. Ro parks at its maximum. That deletes dates but preserves vanished heat and burial, which is exactly what the Expert tier''s erosion signature reads.'),
  ('basin', 'intermediate', 'final', null, 35, 'A 300 m persistent under-burial error and a wrong heating-rate guess of a factor of 3 are', '["similar-sized effects, about 9 versus 7 degrees on every boundary.", "incomparable.", "negligible against tolerance, both being sub-degree effects.", "opposite in sign, so the two errors tend to cancel across the profile."]'::jsonb, 0, 'Geometry slips masquerade as rate errors. 9 degrees of persistent cooling versus the 6 to 9 degree crossing shift per factor of 3. Diagnosing one while committing the other is the classic calibration trap.'),
  ('basin', 'intermediate', 'final', null, 36, 'The five software checks, in cost order, are', '["oracle, build, lint, test, review.", "anchors, monotone range, rate landmarks, fixture crossings, clock separation.", "crossings first, then the anchors, separation, monotone range and rate landmarks.", "anchors, oracle, convergence, review, sign-off."]'::jsonb, 1, 'Free closed forms first, then structure, then landmarks, then graded rows, then the separation test that hunts the documented conflation defect.'),
  ('basin', 'intermediate', 'final', null, 37, 'Halving the integration step on a graded ramp row should', '["halve the answer''s error exactly, by the first-order convergence of the scheme.", "move the answer well inside tolerance, demonstrating convergence.", "leave the answer bit-identical, the scheme being exact at any step.", "double the reflectance."]'::jsonb, 1, 'Demonstrated convergence: at 0.01 Ma the residual error is far below the 1e-9 oracle agreement, so halving changes nothing visible at graded precision.'),
  ('basin', 'intermediate', 'final', null, 38, 'The honest deliverable format this tier teaches is', '["the answer with its assumptions attached.", "the answer alone, concision being the mark of confidence.", "the full bin states.", "a plot without numbers."]'::jsonb, 0, 'Clock, track and pace, spectrum, convention, checks. Assumptions travel with answers because the answer''s meaning depends on them. One auditable sentence per run.'),
  ('basin', 'intermediate', 'final', null, 39, 'The Expert tier will multiply the kerogen clock''s output by', '["the retention cap of the source layer, converting TR directly into expelled mass.", "the vitrinite F.", "the heating rate of the final approach to present day.", "the source''s generative potential in kg/m2."]'::jsonb, 3, 'TR into generated mass. TR times potential is generation. The cap governs expulsion, a separate step; the vitrinite state stays the calibration channel.'),
  ('basin', 'intermediate', 'final', null, 40, 'During the Expert basin''s 76 Ma cooling era, this tier predicts maturity will', '["rise linearly.", "fall gradually back toward the floor as the temperature drops.", "creep: almost, but not quite, nothing, by the stall.", "oscillate with the interpolated heat-flow history."]'::jsonb, 2, 'Cooling parks the front; drained bins stay drained and higher bins react negligibly. Ro rises only marginally, and never falls.'),
  ('basin', 'intermediate', 'final', null, 41, 'The single most load-bearing habit from this tier, per its closing lesson, is', '["quoting the independent oracle''s digits rather than the engine''s.", "memorising the golden ramp tables and both crossing tables.", "preferring hot models.", "keeping the two clocks separate, in code and in reasoning."]'::jsonb, 3, 'The tier above multiplies one clock by a mass and calibrates against the other. Every conflation corrupts both jobs at once.'),
  ('basin', 'intermediate', 'final', null, 42, 'The capstone''s six fields, in clock terms, are', '["six vitrinite readings.", "two closed-form vitrinite anchors, two vitrinite ramp readings.", "three fields per clock, all six of them integrated.", "four kerogen readings and two vitrinite readings, all six integrated."]'::jsonb, 1, 'Two kerogen isothermal readings. Anchors (no integration), Ro at 150 for rates 3 and 1, and Type II TR at 10 and 50 Ma at 100 degC.');
